export function exerciseAlternativeNames(exercise) {
 const record=exerciseAliasResearch[exercise?.id];
 const custom=Array.isArray(exercise?.aliases)?exercise.aliases.filter(x=>typeof x==='string'&&x.trim()):[];
 return {aliases:[...new Set([...(record?.aliases||[]),...custom])],related:record?.related||[],status:record?.status||'unresearched',sources:record?.sources||[]};
}
